  [/^Cours · (.+)$/, (m, a) => `课程 · ${a}`], [/^Projet · (.+)$/, (m, a) => `项目 · ${a}`], [/^Documents › (.+)$/, (m, a) => `文档 › ${a}`],
  [/^(.+), (projet Claude|outil|site|bot)$/, (m, a, t) => `${a}，${tr1(t)}`], [/^Il y a (.+)$/, (m, a) => `${tr1(a)}前`], [/^il y a (.+)$/, (m, a) => `${tr1(a)}前`]
